public static class AudioRepairUiTests {
 static int count,code;static object F(object f,string n){return f.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);}static object C(object f,string n,params object[] a){return f.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,a);}static void Check(bool b,string n){if(!b)throw new Exception(n);Console.WriteLine("PASS "+n);count++;}static IEnumerable<Control> Walk(Control c){foreach(Control child in c.Controls){yield return child;foreach(var n in Walk(child))yield return n;}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var main=new MainForm();var tabs=(TabControl)F(main,"tabs");Check(tabs.TabCount==7&&!tabs.TabPages.Cast<TabPage>().Any(page=>page.Text.Contains("duyệt")),"Seven main tabs remain; removed video workspace is not restored");Check(Walk(tabs.TabPages[0]).OfType<Button>().Any(b=>b.Text=="A/B · sửa câu")&&Walk(tabs.TabPages[1]).OfType<Button>().Any(b=>b.Text=="A/B · sửa câu"),"Studio and queue both expose A/B entry button");string captureDir=Path.Combine(Path.GetTempPath(),"V15 snapshot "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(captureDir);var captureCues=AudioRepairTests.Cues();string captureSource=Path.Combine(captureDir,"record.srt");File.WriteAllText(captureSource,Scripts.ToSrt(captureCues));var captureEngine=new RepairFake{Root=captureDir,VoiceName="A"};var captureOptions=AudioRepair.Options(AudioRepairTests.Settings().Xml().ToString());C(main,"AttachRepairRecording",captureOptions,captureCues,captureEngine,captureSource,AudioRepairTests.Settings().Xml().ToString(),StateFiles.Hash(captureSource));Renderer.Render(VoiceRenderReport.Snapshot(captureCues),captureEngine,captureOptions,Path.Combine(captureDir,"record.wav"),(i,m)=>{});var recorded=RepairSession.Open(captureSource,captureCues,(string)F(main,"stateDir"),false);Check(recorded.Parts.All(part=>part.HasAudio),"Standard Studio recording hook persists exact repair background");main.Dispose();
 string dir=Path.Combine(Path.GetTempPath(),"V15 repair UI "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var cues=AudioRepairTests.Cues();string source=Path.Combine(dir,"story.srt");File.WriteAllText(source,Scripts.ToSrt(cues));var p=RepairSession.Open(source,cues,dir,false);p.Settings=AudioRepairTests.Settings().Xml().ToString();var profiles=new List<VoiceProfile>{new VoiceProfile{Key="K:0",Name="ADAM test A",Kind=EngineKind.Kokoro,Speaker=0},new VoiceProfile{Key="K:1",Name="EXCITER test B",Kind=EngineKind.Kokoro,Speaker=1}};
 var f=new AudioRepairDialog(p,cues,1,profiles,v=>new RepairFake{Root=dir,VoiceName=v.Name,Speaker=v.Speaker,Seconds=v.Speaker==0?4.12:3.1});f.Shown+=async(s,e)=>{try{
  var rows=(DataGridView)F(f,"rows");var editor=(TextBox)F(f,"editor");Console.WriteLine("OPEN ROW="+rows.Rows.Count+" current="+rows.CurrentRow.Index+" editor="+editor.Text);Check(rows.Rows.Count==3&&rows.CurrentRow.Index==1&&editor.Text==cues[1].Text,"Opening A/B targets selected cue and current text");Check(((Label)F(f,"scope")).Text.Contains("một câu"),"Dialog labels single-cue repair scope");Check(!((Button)F(f,"applyA")).Enabled&&!((Button)F(f,"applyB")).Enabled,"Apply is disabled before real measurement");
  await(Task)C(f,"TrialBoth");Check(p.Parts[1].A.Success&&p.Parts[1].B.Success,"Two different voices are rendered and measured through UI");Check(((Label)F(f,"metricA")).Text.Contains("kết thúc lời")&&((Label)F(f,"metricB")).Text.Contains("Nghỉ cuối"),"UI separates speech end and tail silence");Check(((Button)F(f,"applyB")).Enabled,"Measured valid B can be adopted");Check(((CheckBox)F(f,"natural")).Text=="Nghe tự nhiên","UI offers original versus fitted audition");((CheckBox)F(f,"natural")).Checked=true;Check(Math.Abs(((Wave)F(f,"showA")).Duration-p.Parts[1].A.Natural)<.001,"Natural audition toggle also displays natural waveform");((CheckBox)F(f,"natural")).Checked=false;
  editor.Text="Edited words in this sentence.";Check(!((Button)F(f,"applyB")).Enabled,"Changing text disables stale adoption");editor.Text=cues[1].Text;Check(((Button)F(f,"applyB")).Enabled,"Restoring exact text reuses matching measured candidate");
  ((ComboBox)F(f,"voiceB")).SelectedIndex=0;Check(!((Button)F(f,"applyB")).Enabled,"Changing selected voice invalidates stale comparison");((ComboBox)F(f,"voiceB")).SelectedIndex=1;
  await(Task)C(f,"Adopt",false);Check(f.Published&&File.Exists(p.Output)&&FinalAudio.PcmFrames(p.Output)==302400,"Adopt B prepares missing intervals and publishes exact WAV");Check(File.ReadAllText(source)==Scripts.ToSrt(cues),"UI leaves source SRT untouched");Check(f.PublishedWav==p.Output&&f.PublishedWords.Count==3&&f.PublishedReport==p.Report,"Dialog returns a separate successfully published snapshot");Check(p.Effective().Select(c=>c.Id).SequenceEqual(new[]{1,2,3}),"UI rows retain original sentence numbering after background creation");Check(p.Parts[1].Selected.Voice==profiles[1].Name,"Chosen B voice persists in selected part");
  string goodOutput=p.Output,goodSignature=p.Signature;var goodTake=p.Parts[1].Selected;p.Signature="changed";await(Task)C(f,"Adopt",true);Check(p.Output==goodOutput&&p.Parts[1].Selected==goodTake&&f.PublishedWords[1].Text==cues[1].Text,"Failed later adoption rolls back selected take and keeps published snapshot");p.Signature=goodSignature;p.Save();C(f,"Busy",true);Check(!rows.Enabled&&!editor.Enabled&&((Button)F(f,"stop")).Enabled,"Busy state locks edits and preserves Stop");C(f,"Busy",false);Check(rows.Enabled&&editor.Enabled,"Controls unlock after work");
  f.Size=new Size(1050,740);f.Location=new Point(0,0);Application.DoEvents();Check(rows.Height>=100&&editor.Height>=40&&((Panel)F(f,"waves")).Height>=80,"Minimum window keeps sentence list editor and waveform visible");Check(((Button)F(f,"applyA")).Visible&&((Button)F(f,"applyB")).Visible,"Both primary actions stay visible");using(var bitmap=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(f.Location,Point.Empty,f.Size);bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation","audio-repair209-min.png"));}
  C(f,"Navigate",1);Check(rows.CurrentRow.Index==2,"Next cue navigation moves within same SRT");Console.WriteLine("TOTAL AUDIO REPAIR UI "+count+" passed.");
 }catch(Exception ex){Console.WriteLine(ex);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
